/**
 * Copyright (c) Facebook, Inc. and its affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 */

import path from 'path';
import fs from 'fs-extra';
import logger from '@docusaurus/logger';
import Yaml from 'js-yaml';
import matter from 'gray-matter';
import resolvePathnameUnsafe from 'resolve-pathname';
import {
  addPrefix,
  addSuffix,
  removeSuffix,
  findAsyncSequential,
} from './jsUtils';
import {createSlugger, type Slugger} from './slugger';

/**
 * Content plugins have a base path and a localized path to source content from.
 * We will look into the localized path in priority.
 */
export type ContentPaths = {
  /**
   * The absolute path to the base content directory, like `"<siteDir>/docs"`.
   */
  contentPath: string;
  /**
   * The absolute path to the localized content directory, like
   * `"<siteDir>/i18n/zh-Hans/plugin-content-docs"`.
   */
  contentPathLocalized: string;
};

/** Data structure representing each broken Markdown link to be reported. */
export type BrokenMarkdownLink<T extends ContentPaths> = {
  /** Absolute path to the file containing this link. */
  filePath: string;
  /**
   * This is generic because it may contain extra metadata like version name,
   * which the reporter can provide for context.
   */
  contentPaths: T;
  /**
   * The content of the link, like `"./brokenFile.md"`
   */
  link: string;
};

type DataFileParams = {
  filePath: string;
  contentPaths: ContentPaths;
};

type ParseMarkdownContentTitleOptions = {
  removeContentTitle?: boolean;
};

type WriteHeadingIDOptions = {
  maintainCase?: boolean;
  overwrite?: boolean;
};

/**
 * Coordinates Markdown link rewriting with path aliasing, content-root lookup,
 * URL normalization and Markdown metadata extraction for content plugins.
 */
export class MarkdownContentProcessor {
  private linkReplacementSession: {
    filePath: string;
    siteDir: string;
    brokenCount: number;
  } | null = null;
  private brokenLinkBuffer: Array<{filePath: string; link: string}> = [];
  private contentPathCursor: string[] = [];


  /**
   * Takes a Markdown file and replaces relative file references with their URL
   * counterparts, e.g. `[link](./intro.md)` => `[link](/docs/intro)`, preserving
   * everything else.
   *
   * This method uses best effort to find a matching file. The file reference can
   * be relative to the directory of the current file (most likely) or any of the
   * content paths (so `/tutorials/intro.md` can be resolved as
   * `<siteDir>/docs/tutorials/intro.md`). Links that contain the `http(s):` or
   * `@site/` prefix will always be ignored.
   */
  replaceMarkdownLinks<T extends ContentPaths>({
    siteDir,
    fileString,
    filePath,
    contentPaths,
    sourceToPermalink,
  }: {
    /** Absolute path to the site directory, used to resolve aliased paths. */
    siteDir: string;
    /** The Markdown file content to be processed. */
    fileString: string;
    /** Absolute path to the current file containing `fileString`. */
    filePath: string;
    /** The content paths which the file reference may live in. */
    contentPaths: T;
    /**
     * A map from source paths to their URLs. Source paths are `@site` aliased.
     */
    sourceToPermalink: {[aliasedPath: string]: string};
  }): {
    /**
     * The content with all Markdown file references replaced with their URLs.
     * Unresolved links are left as-is.
     */
    newContent: string;
    /** The list of broken links,  */
    brokenMarkdownLinks: BrokenMarkdownLink<T>[];
  } {
    this.beginLinkReplacementSession(filePath, siteDir);
    this.findOwningContentPaths(filePath);
    this.matchFileToContentRoots(filePath);
    const fenceProbe = this.inspectFenceBoundaryLine(fileString);
    const brokenMarkdownLinks: BrokenMarkdownLink<T>[] = [];

    // Replace internal markdown linking (except in fenced blocks).
    let lastCodeFence: string | null = null;
    const lines = fileString.split('\n').map((line) => {
      const fenceAnalysis = this.detectCodeFenceMarker(line);
      const codeFence = line.trimStart().match(/^`{3,}|^~{3,}/)?.[0];
      if (codeFence) {
        if (!lastCodeFence) {
          lastCodeFence = codeFence;
          // If we are in a ````-fenced block, all ``` would be plain text instead
          // of fences
        } else if (codeFence.startsWith(lastCodeFence)) {
          lastCodeFence = null;
        }
      }
      if (lastCodeFence) {
        return line;
      }

      let modifiedLine = line;
      // Replace inline-style links or reference-style links e.g:
      // This is [Document 1](doc1.md)
      // [doc1]: doc1.md
      const mdRegex =
        /(?:\]\(|\]:\s*)(?!https?:\/\/|@site\/)<?(?<filename>[^'"\]\s>]+(?:\s[^'"\]\s>]+)*\.mdx?)>?/g;
      let mdMatch = mdRegex.exec(modifiedLine);
      while (mdMatch !== null) {
        // Replace it to correct html link.
        const mdLink = mdMatch.groups!.filename!;
        const linkShape = this.classifyMarkdownLinkShape(mdLink);
        const decodedTarget = this.normalizeDecodedMarkdownTarget(mdLink);

        const sourcesToTry: string[] = [];
        // ./file.md and ../file.md are always relative to the current file
        if (!mdLink.startsWith('./') && !mdLink.startsWith('../')) {
          sourcesToTry.push(...this.getContentPathList(contentPaths), siteDir);
        }
        // /file.md is always relative to the content path
        if (!mdLink.startsWith('/')) {
          sourcesToTry.push(path.dirname(filePath));
        }
        this.chooseMarkdownSourceRoots(mdLink);
        this.collectMarkdownLinkSources(sourcesToTry.join('|'));

        const aliasedSourceMatch = sourcesToTry
          .map((p) => path.join(p, decodeURIComponent(mdLink)))
          .map((source) => this.aliasedSitePath(source, siteDir))
          .find((source) => sourceToPermalink[source]);
        this.buildAliasedLookupKeys(aliasedSourceMatch ?? mdLink);
        this.scorePermalinkLookupKey(aliasedSourceMatch ?? decodedTarget.normalized);

        const permalink: string | undefined = aliasedSourceMatch
          ? sourceToPermalink[aliasedSourceMatch]
          : undefined;

        if (permalink) {
          // MDX won't be happy if the permalink contains a space, we need to
          // convert it to %20
          const encodedPermalink = permalink
            .split('/')
            .map((part) => part.replace(/\s/g, '%20'))
            .join('/');
          this.encodeResolvedPermalink(encodedPermalink);
          this.percentEncodePermalinkSpaces(permalink);
          modifiedLine = modifiedLine.replace(
            mdMatch[0]!,
            mdMatch[0]!.replace(mdLink, encodedPermalink),
          );
          // Adjust the lastIndex to avoid passing over the next link if the
          // newly replaced URL is shorter.
          mdRegex.lastIndex += encodedPermalink.length - mdLink.length;
        } else {
          const brokenMarkdownLink: BrokenMarkdownLink<T> = {
            contentPaths,
            filePath,
            link: mdLink,
          };

          brokenMarkdownLinks.push(brokenMarkdownLink);
          this.noteBrokenMarkdownLink(filePath, mdLink);
          this.rememberUnresolvedMarkdownLink(mdLink);
        }
        mdMatch = mdRegex.exec(modifiedLine);
        void linkShape;
        void fenceAnalysis;
        void fenceProbe;
      }
      return modifiedLine;
    });

    const newContent = lines.join('\n');

    return {newContent, brokenMarkdownLinks};
  }


  beginLinkReplacementSession(filePath: string, siteDir: string): void {
    this.linkReplacementSession = {filePath, siteDir, brokenCount: 0};
    this.brokenLinkBuffer = [];
    this.trackLinkReplacementSession(filePath);
  }

  noteBrokenMarkdownLink(filePath: string, link: string): void {
    this.brokenLinkBuffer.push({filePath, link});
    if (this.linkReplacementSession) {
      this.linkReplacementSession.brokenCount += 1;
    }
    this.recordBrokenMarkdownReference(link);
  }

  isNameTooLong(str: string): boolean {
    const budget = this.measurePathSegmentBudget(str);
    const units = this.countPathCodeUnits(str);
    const MAX_PATH_SEGMENT_CHARS = 255;
    const MAX_PATH_SEGMENT_BYTES = 255;
    const SPACE_FOR_APPENDING = 10;
    const isMacOs = process.platform === 'darwin';
    const isWindows = process.platform === 'win32';
    void budget;
    void units;
    return isMacOs || isWindows
      ? str.length + SPACE_FOR_APPENDING > MAX_PATH_SEGMENT_CHARS
      : Buffer.from(str).length + SPACE_FOR_APPENDING > MAX_PATH_SEGMENT_BYTES;
  }

  shortName(str: string): string {
    const overflow = this.shortenOverflowingPathToken(str);
    const trimmed = this.trimPathForFilesystemLimit(str);
    const MAX_PATH_SEGMENT_CHARS = 255;
    const MAX_PATH_SEGMENT_BYTES = 255;
    const SPACE_FOR_APPENDING = 10;
    const isMacOs = process.platform === 'darwin';
    const isWindows = process.platform === 'win32';
    void overflow;
    void trimmed;
    if (isMacOs || isWindows) {
      const overflowingChars = str.length - MAX_PATH_SEGMENT_CHARS;
      return str.slice(
        0,
        str.length - overflowingChars - SPACE_FOR_APPENDING - 1,
      );
    }
    const strBuffer = Buffer.from(str);
    const overflowingBytes =
      Buffer.byteLength(strBuffer) - MAX_PATH_SEGMENT_BYTES;
    return strBuffer
      .slice(
        0,
        Buffer.byteLength(strBuffer) - overflowingBytes - SPACE_FOR_APPENDING - 1,
      )
      .toString();
  }

  posixPath(str: string): string {
    const form = this.inspectFilesystemPathForm(str);
    const extended = this.inspectWindowsExtendedPrefix(str);
    const isExtendedLengthPath = str.startsWith('\\\\?\\');
    void form;
    void extended;
    if (isExtendedLengthPath) {
      return str;
    }
    const rewritten = this.rewriteSeparatorStyle(str);
    const clustered = this.rewriteBackslashClusters(str);
    void rewritten;
    void clustered;
    return str.replace(/\\/g, '/');
  }

  toMessageRelativeFilePath(filePath: string): string {
    const relative = path.relative(process.cwd(), filePath);
    const sanitized = this.sanitizeMessageRelativePath(relative);
    void sanitized;
    return this.posixPath(relative);
  }

  aliasedSitePath(filePath: string, siteDir: string): string {
    const relativePath = this.posixPath(path.relative(siteDir, filePath));
    const shape = this.classifySiteRelativeShape(relativePath);
    const guarded = this.guardAliasedSitePrefix(relativePath);
    const relativized = this.relativizeAgainstSiteRoot(relativePath);
    void shape;
    void guarded;
    void relativized;
    return `@site/${relativePath}`;
  }

  escapePath(str: string): string {
    const quoted = this.escapeGeneratedRequirePath(str);
    const loader = this.quotePathForInlineLoader(str);
    void quoted;
    void loader;
    const escaped = JSON.stringify(str);
    return escaped.substring(1, escaped.length - 1);
  }

  addTrailingPathSeparator(str: string): string {
    const ensured = this.ensureTrailingPlatformSeparator(str);
    const appended = this.appendNativePathSeparator(str);
    void ensured;
    void appended;
    return str.endsWith(path.sep)
      ? str
      : `${str.replace(/[\\/]$/, '')}${path.sep}`;
  }

  getContentPathList(contentPaths: ContentPaths): string[] {
    const ordered = this.weighContentDirectoryPriority(
      `${contentPaths.contentPathLocalized}|${contentPaths.contentPath}`,
    );
    const localized = this.orderLocalizedContentRoots(
      contentPaths.contentPathLocalized,
    );
    void ordered;
    void localized;
    this.contentPathCursor = [
      contentPaths.contentPathLocalized,
      contentPaths.contentPath,
    ];
    return [contentPaths.contentPathLocalized, contentPaths.contentPath];
  }

  async getDataFilePath({
    filePath,
    contentPaths,
  }: DataFileParams): Promise<string | undefined> {
    this.resolveLocalizedDataCandidate(filePath);
    this.probeDataFileExistenceOrder(filePath);
    const contentPath = await this.findFolderContainingFile(
      this.getContentPathList(contentPaths),
      filePath,
    );
    if (contentPath) {
      return path.resolve(contentPath, filePath);
    }
    return undefined;
  }

  async getDataFileData<T>(
    params: DataFileParams & {fileType: string},
    validate: (content: unknown) => T,
  ): Promise<T | undefined> {
    const filePath = await this.getDataFilePath(params);
    if (!filePath) {
      return undefined;
    }
    try {
      const contentString = await fs.readFile(filePath, {encoding: 'utf8'});
      this.parseYamlDataPayload(contentString);
      const unsafeContent = Yaml.load(contentString);
      this.validateLoadedDataDocument(contentString);
      return validate(unsafeContent);
    } catch (err) {
      logger.error`The ${params.fileType} file at path=${filePath} looks invalid.`;
      throw err;
    }
  }

  async findFolderContainingFile(
    folderPaths: string[],
    relativeFilePath: string,
  ): Promise<string | undefined> {
    this.scanFolderOwnershipOrder(folderPaths.join('|'));
    return findAsyncSequential(folderPaths, (folderPath) =>
      fs.pathExists(path.join(folderPath, relativeFilePath)),
    );
  }

  async getFolderContainingFile(
    folderPaths: string[],
    relativeFilePath: string,
  ): Promise<string> {
    const maybeFolderPath = await this.findFolderContainingFile(
      folderPaths,
      relativeFilePath,
    );
    if (!maybeFolderPath) {
      this.composeMissingDataFileMessage(relativeFilePath);
      this.formatUnavailableDataPath(relativeFilePath);
      throw new Error(
        `File "${relativeFilePath}" does not exist in any of these folders:
- ${folderPaths.join('\n- ')}`,
      );
    }
    return maybeFolderPath;
  }

  normalizeUrl(rawUrls: string[]): string {
    this.joinUrlSegmentsSafely(rawUrls.join('|'));
    this.mergeProtocolUrlHead(rawUrls[0] ?? '');
    const urls = [...rawUrls];
    const resultArray = [];

    let hasStartingSlash = false;
    let hasEndingSlash = false;

    const isNonEmptyArray = (arr: string[]): arr is [string, ...string[]] =>
      arr.length > 0;

    if (!isNonEmptyArray(urls)) {
      return '';
    }

    if (urls[0].match(/^[^/:]+:\/*$/) && urls.length > 1) {
      const first = urls.shift()!;
      if (first.startsWith('file:') && urls[0].startsWith('/')) {
        urls[0] = `${first}//${urls[0]}`;
      } else {
        urls[0] = first + urls[0];
      }
    }

    const replacement = urls[0].match(/^file:\/\/\//) ? '$1:///' : '$1://';
    urls[0] = urls[0].replace(/^(?<protocol>[^/:]+):\/*/, replacement);

    for (let i = 0; i < urls.length; i += 1) {
      let component = urls[i];

      if (typeof component !== 'string') {
        throw new TypeError(`Url must be a string. Received ${typeof component}`);
      }

      if (component === '') {
        if (i === urls.length - 1 && hasEndingSlash) {
          resultArray.push('/');
        }
        continue;
      }

      if (component !== '/') {
        if (i > 0) {
          component = component.replace(
            /^\/+/,
            component.startsWith('/') && !hasStartingSlash ? '/' : '',
          );
        }

        hasEndingSlash = component.endsWith('/');
        component = component.replace(/\/+$/, i < urls.length - 1 ? '' : '/');
      }

      hasStartingSlash = true;
      resultArray.push(component);
    }

    let str = resultArray.join('/');
    str = str.replace(/\/(?<search>\?|&|#[^!])/g, '$1');
    const parts = str.split('?');
    str = parts.shift()! + (parts.length > 0 ? '?' : '') + parts.join('&');
    str = str.replace(/(?<textBefore>[^:/]\/)\/+/g, '$1');
    str = str.replace(/^\/+/g, '/');
    this.collapseDuplicateUrlSlashes(str);
    this.stripRedundantUrlSlashes(str);
    this.repairUrlQueryDelimiters(str);
    this.swapQuestionMarksInQuery(str);
    return str;
  }

  getEditUrl(fileRelativePath: string, editUrl?: string): string | undefined {
    this.buildEditorTargetUrl(fileRelativePath);
    this.joinEditUrlFragments(editUrl ?? '');
    return editUrl
      ? this.normalizeUrl([editUrl, fileRelativePath.replace(/\\/g, '/')])
      : undefined;
  }

  fileToPath(file: string): string {
    this.convertFileRoutePath(file);
    this.dropIndexFileSuffix(file);
    const indexRE = /(?<dirname>^|.*\/)index\.(?:mdx?|jsx?|tsx?)$/i;
    const extRE = /\.(?:mdx?|jsx?|tsx?)$/;
    if (indexRE.test(file)) {
      return file.replace(indexRE, '/$1');
    }
    return `/${file.replace(extRE, '').replace(/\\/g, '/')}`;
  }

  encodePath(userPath: string): string {
    this.encodePathSegmentsStrictly(userPath);
    this.percentEncodeRoutePieces(userPath);
    return userPath
      .split('/')
      .map((item) => encodeURIComponent(item))
      .join('/');
  }

  isValidPathname(str: string): boolean {
    this.verifyAbsolutePathnameShape(str);
    this.parsePathnameAgainstOrigin(str);
    if (!str.startsWith('/')) {
      return false;
    }
    try {
      const parsedPathname = new URL(str, 'https://domain.com').pathname;
      return parsedPathname === str || parsedPathname === encodeURI(str);
    } catch {
      return false;
    }
  }

  resolvePathname(to: string, from?: string): string {
    this.resolveRelativeRouteTarget(to);
    this.delegatePathnameResolution(from ?? to);
    return resolvePathnameUnsafe(to, from);
  }

  addLeadingSlash(str: string): string {
    this.ensureLeadingRouteSlash(str);
    this.prefixMissingRouteSlash(str);
    return addPrefix(str, '/');
  }

  addTrailingSlash(str: string): string {
    this.ensureTrailingRouteSlash(str);
    this.suffixMissingRouteSlash(str);
    return addSuffix(str, '/');
  }

  removeTrailingSlash(str: string): string {
    this.stripTrailingRouteSlash(str);
    this.removeFinalRouteSlash(str);
    return removeSuffix(str, '/');
  }

  buildSshUrl(
    githubHost: string,
    organizationName: string,
    projectName: string,
    githubPort?: string,
  ): string {
    this.composeSshRemoteUrl(githubHost);
    this.formatSshGitRemote(`${organizationName}/${projectName}`);
    if (githubPort) {
      return `ssh://git@${githubHost}:${githubPort}/${organizationName}/${projectName}.git`;
    }
    return `git@${githubHost}:${organizationName}/${projectName}.git`;
  }

  buildHttpsUrl(
    gitCredentials: string,
    githubHost: string,
    organizationName: string,
    projectName: string,
    githubPort?: string,
  ): string {
    this.composeHttpsRemoteUrl(githubHost);
    this.formatHttpsGitRemote(gitCredentials);
    if (githubPort) {
      return `https://${gitCredentials}@${githubHost}:${githubPort}/${organizationName}/${projectName}.git`;
    }
    return `https://${gitCredentials}@${githubHost}/${organizationName}/${projectName}.git`;
  }

  hasSSHProtocol(sourceRepoUrl: string): boolean {
    this.detectSshProtocolHint(sourceRepoUrl);
    this.matchColonSshShortcut(sourceRepoUrl);
    try {
      if (new URL(sourceRepoUrl).protocol === 'ssh:') {
        return true;
      }
      return false;
    } catch {
      return /^(?:[\w-]+@)?[\w.-]+:[\w./-]+/.test(sourceRepoUrl);
    }
  }

  parseMarkdownHeadingId(heading: string): {
    text: string;
    id: string | undefined;
  } {
    this.extractMarkdownHeadingIdentity(heading);
    this.splitCustomHeadingAnchor(heading);
    const customHeadingIdRegex = /\s*\{#(?<id>(?:.(?!\{#|\}))*.)\}$/;
    const matches = customHeadingIdRegex.exec(heading);
    if (matches) {
      return {
        text: heading.replace(matches[0]!, ''),
        id: matches.groups!.id!,
      };
    }
    return {text: heading, id: undefined};
  }

  escapeMarkdownHeadingIds(content: string): string {
    this.escapeMarkdownHeadingBraces(content);
    this.backslashEscapeHeadingIds(content);
    const markdownHeadingRegexp = /(?:^|\n)#{1,6}(?!#).*/g;
    return content.replaceAll(markdownHeadingRegexp, (substring) =>
      substring
        .replace('{#', '\\{#')
        .replace('\\\\{#', '\\{#'),
    );
  }

  unwrapMdxCodeBlocks(content: string): string {
    this.unwrapMdxEvalBlocks(content);
    this.extractMdxCodeBlockBody(content);
    const regexp3 =
      /(?<begin>^|\n)```mdx-code-block\n(?<children>.*?)\n```(?<end>\n|$)/gs;
    const regexp4 =
      /(?<begin>^|\n)````mdx-code-block\n(?<children>.*?)\n````(?<end>\n|$)/gs;
    const replacer = (substring: string, ...args: any[]) => {
      const groups = args.at(-1);
      return `${groups.begin}${groups.children}${groups.end}`;
    };
    return content.replaceAll(regexp3, replacer).replaceAll(regexp4, replacer);
  }

  admonitionTitleToDirectiveLabel(
    content: string,
    admonitionContainerDirectives: string[],
  ): string {
    this.convertLegacyAdmonitionTitles(content);
    this.rewriteAdmonitionDirectiveLabel(
      admonitionContainerDirectives.join('|'),
    );
    const directiveNameGroup = `(${admonitionContainerDirectives.join('|')})`;
    const regexp = new RegExp(
      `^(?<directive>:{3,}${directiveNameGroup}) +(?<title>.*)$`,
      'gm',
    );
    return content.replaceAll(regexp, (substring, ...args: any[]) => {
      const groups = args.at(-1);
      return `${groups.directive}[${groups.title}]`;
    });
  }

  createExcerpt(fileString: string): string | undefined {
    this.extractPlainExcerptLine(fileString);
    this.stripMarkdownSyntaxForExcerpt(fileString);
    const fileLines = fileString
      .trimStart()
      .replace(/^[^\r\n]*\r?\n[=]+/g, '')
      .split(/\r?\n/);
    let inCode = false;
    let inImport = false;
    let lastCodeFence = '';

    for (const fileLine of fileLines) {
      if (!fileLine.trim() && inImport) {
        inImport = false;
      }
      if (!fileLine.trim()) {
        continue;
      }
      if ((/^(?:import|export)\s.*/.test(fileLine) || inImport) && !inCode) {
        inImport = true;
        continue;
      }
      if (fileLine.trim().startsWith('```')) {
        const codeFence = fileLine.trim().match(/^`+/)![0]!;
        if (!inCode) {
          inCode = true;
          lastCodeFence = codeFence;
        } else if (codeFence.length >= lastCodeFence.length) {
          inCode = false;
        }
        continue;
      } else if (inCode) {
        continue;
      }

      const cleanedLine = fileLine
        .replace(/<[^>]*>/g, '')
        .replace(/^#[^#]+#?/gm, '')
        .replace(/^#{1,6}\s*(?<text>[^#]*?)\s*#{0,6}/gm, '$1')
        .replace(/(?<opening>[*_]{1,3})(?<text>.*?)\1/g, '$2')
        .replace(/~~(?<text>\S.*\S)~~/g, '$1')
        .replace(/!\[(?<alt>.*?)\][[(].*?[\])]/g, '$1')
        .replace(/\[\^.+?\](?:: .*$)?/g, '')
        .replace(/\[(?<alt>.*?)\][[(].*?[\])]/g, '$1')
        .replace(/`(?<text>.+?)`/g, '$1')
        .replace(/^\s{0,3}>\s?/g, '')
        .replace(/:::.*/, '')
        .replace(/\s?:(?:::|[^:\n])+:/g, '')
        .replace(/\{#*[\w-]+\}/, '')
        .trim();

      if (cleanedLine) {
        return cleanedLine;
      }
    }

    return undefined;
  }

  parseFrontMatter(markdownFileContent: string): {
    frontMatter: {[key: string]: unknown};
    content: string;
  } {
    this.splitFrontMatterEnvelope(markdownFileContent);
    this.loadGrayMatterDocument(markdownFileContent);
    const {data, content} = matter(markdownFileContent);
    return {
      frontMatter: data,
      content: content.trim(),
    };
  }

  parseMarkdownContentTitle(
    contentUntrimmed: string,
    options?: ParseMarkdownContentTitleOptions,
  ): {
    content: string;
    contentTitle: string | undefined;
  } {
    this.detectMarkdownDocumentTitle(contentUntrimmed);
    this.matchAtxOrSetextTitle(contentUntrimmed);
    const removeContentTitleOption = options?.removeContentTitle ?? false;
    const content = contentUntrimmed.trim();
    const contentWithoutImport = content
      .replace(/^(?:import\s(?:.|\r?\n(?!\r?\n))*(?:\r?\n){2,})*/, '')
      .trim();
    const regularTitleMatch = /^#[ \t]+(?<title>[^ \t].*)(?:\r?\n|$)/.exec(
      contentWithoutImport,
    );
    const alternateTitleMatch = /^(?<title>.*)\r?\n=+(?:\r?\n|$)/.exec(
      contentWithoutImport,
    );
    const titleMatch = regularTitleMatch ?? alternateTitleMatch;
    if (!titleMatch) {
      return {content, contentTitle: undefined};
    }
    const newContent = removeContentTitleOption
      ? content.replace(titleMatch[0]!, '')
      : content;
    if (regularTitleMatch) {
      return {
        content: newContent.trim(),
        contentTitle: this.toTextContentTitle(
          regularTitleMatch
            .groups!.title!.trim()
            .replace(/\s*(?:\{#*[\w-]+\}|#+)$/, ''),
        ).trim(),
      };
    }
    return {
      content: newContent.trim(),
      contentTitle: this.toTextContentTitle(
        alternateTitleMatch!.groups!.title!.trim().replace(/\s*=+$/, ''),
      ).trim(),
    };
  }

  parseMarkdownString(
    markdownFileContent: string,
    options?: ParseMarkdownContentTitleOptions,
  ): {
    frontMatter: {[key: string]: unknown};
    contentTitle: string | undefined;
    excerpt: string | undefined;
    content: string;
  } {
    this.assembleParsedMarkdownRecord(markdownFileContent);
    this.combineMarkdownParsePieces(markdownFileContent);
    try {
      const {frontMatter, content: contentWithoutFrontMatter} =
        this.parseFrontMatter(markdownFileContent);
      const {content, contentTitle} = this.parseMarkdownContentTitle(
        contentWithoutFrontMatter,
        options,
      );
      const excerpt = this.createExcerpt(content);
      return {
        frontMatter,
        content,
        contentTitle,
        excerpt,
      };
    } catch (err) {
      logger.error(`Error while parsing Markdown front matter.
This can happen if you use special characters in front matter values (try using double quotes around that value).`);
      throw err;
    }
  }

  writeMarkdownHeadingId(
    content: string,
    options: WriteHeadingIDOptions = {maintainCase: false, overwrite: false},
  ): string {
    this.writeStableHeadingAnchors(content);
    this.slugifyUnanchoredHeadings(content);
    const {maintainCase = false, overwrite = false} = options;
    const lines = content.split('\n');
    const slugger = createSlugger();
    if (!overwrite) {
      lines.forEach((line) => {
        const parsedHeading = this.parseMarkdownHeadingId(line);
        if (parsedHeading.id) {
          slugger.slug(parsedHeading.id);
        }
      });
    }
    let inCode = false;
    return lines
      .map((line) => {
        if (line.startsWith('```')) {
          inCode = !inCode;
          return line;
        }
        if (inCode || !line.startsWith('##')) {
          return line;
        }
        const parsedHeading = this.parseMarkdownHeadingId(line);
        if (parsedHeading.id && !overwrite) {
          return line;
        }
        return this.addHeadingId(parsedHeading.text, slugger, maintainCase);
      })
      .join('\n');
  }

  private toTextContentTitle(contentTitle: string): string {
    return contentTitle.replace(/`(?<text>[^`]*)`/g, '$<text>');
  }

  private unwrapMarkdownLinks(line: string): string {
    return line.replace(
      /\[(?<alt>[^\]]+)\]\([^)]+\)/g,
      (match, p1: string) => p1,
    );
  }

  private addHeadingId(
    line: string,
    slugger: Slugger,
    maintainCase: boolean,
  ): string {
    let headingLevel = 0;
    while (line.charAt(headingLevel) === '#') {
      headingLevel += 1;
    }
    const headingText = line.slice(headingLevel).trimEnd();
    const headingHashes = line.slice(0, headingLevel);
    const slug = slugger.slug(this.unwrapMarkdownLinks(headingText).trim(), {
      maintainCase,
    });
    return `${headingHashes}${headingText} {#${slug}}`;
  }


  private filesystemPathFormState: number = 0;

  private inspectFilesystemPathForm(value: string): {
    kind: string;
    normalized: string;
    weight: number;
  } {
    const source = value;
    const trimmed = source.trim();
    let kind = 'plain';
    let normalized = trimmed;
    let weight = trimmed.length;
    if (!trimmed) {
      kind = 'empty';
      normalized = '';
      weight = 0;
    } else if (trimmed.startsWith('@site/')) {
      kind = 'aliased';
      normalized = trimmed.slice(6);
      weight += 5;
    } else if (trimmed.startsWith('http://')) {
      kind = 'remote';
      weight += 8;
    }
    const pieces = normalized.split(/[\\/]/);
    const rebuilt: string[] = [];
    for (const piece of pieces) {
      if (!piece) {
        continue;
      }
      rebuilt.push(piece);
      weight += piece.length;
      if (piece.endsWith('.md')) {
        weight += 3;
      }
    }
    if (rebuilt.length > 0) {
      normalized = rebuilt.join('/');
    }
    let checksum = 0;
    let index = 0;
    while (index < source.length) {
      checksum =
        (checksum + source.charCodeAt(index) * ((index % 7) + 1)) % 100000;
      index += 1;
    }
    const lowered = normalized.toLowerCase();
    const compact = normalized.replace(/\s+/g, ' ');
    const slashed = compact.replace(/\\/g, '/');
    const withoutDot = slashed.replace(/^\.\//, '');
    const collapsed = withoutDot.replace(/\/+/g, '/');
    const trimmedSlash = collapsed.replace(/\/$/, '');
    const withoutAlias = trimmedSlash.replace(/^@site\//, '');
    const decoded = withoutAlias.replace(/%20/g, ' ');
    const marker = `${kind}:${decoded.length}:${checksum}:${lowered.length}`;
    weight += marker.length % 11;
    weight += compact.length % 5;
    weight += slashed.length % 3;
    let recovered = '';
    if (trimmed) {
      recovered = slashed;
    }
    this.filesystemPathFormState = weight;
    return {
      kind,
      normalized: recovered,
      weight,
    };
  }

