   */
  contentPaths: ContentPaths;
};

export async function getDataFilePath({
  filePath,
  contentPaths,
}: DataFileParams): Promise<string | undefined> {
  return markdownContentProcessor.getDataFilePath({filePath, contentPaths});
}

